import{d as u,C as t,o as c,c as g,j as a,a as s,E as n,a3 as m}from"./chunks/framework.Q4yG9rk_.js";const y=JSON.parse('{"title":"道德经第十五章","description":"以七个譬喻体会善为士者的容貌，再看静与动、不欲盈的关系。","frontmatter":{"title":"道德经第十五章","description":"以七个譬喻体会善为士者的容貌，再看静与动、不欲盈的关系。","category":"guide","aliases":["道德经第十五章","老子第十五章","dao de jing chapter 15"],"source":["王弼《道德真经注》卷一"]},"headers":[],"relativePath":"daoism/dao-de-jing/chapter-15.md","filePath":"daoism/dao-de-jing/chapter-15.md","lastUpdated":1794189804000}'),b={name:"daoism/dao-de-jing/chapter-15.md"},_=u({...b,setup(p){const o=[{id:"difficult-to-describe",label:"微妙玄通，深不可识",showLabel:!0,sentences:[["古之善为",{text:"士",glossary:"shi"},"者，微妙玄通，深不可识。"],["夫唯不可识，故",{text:"强",glossary:"qiang"},"为之",{text:"容",glossary:"rong"},"："]],note:["【白话】古时善于修养、行道的人，精微幽深而通达，深到难以识尽。正因为难以识尽，所以只能勉强为他们描摹形容。","【读法】强读 qiǎng，表示不得已勉作描绘；容指容貌、形态。下面七个若都是譬喻，不是把有道者列成可凭外貌打分的七项标准。"]},{id:"care-in-facing-the-world",label:"豫兮若冬涉川",showLabel:!0,sentences:[[{text:"豫",glossary:"yu"},"兮若冬涉川；"],[{text:"犹",glossary:"you"},"兮若畏四邻；"]],note:["【白话】谨慎迟疑啊，像冬天踏水过河；警惕顾虑啊，像担心四面的邻人。两个形象都让人感到不轻率行动、未把意图显露无遗。","【王弼注择要】「若欲度，若不欲度，其情不可得见之貌也。」又说「上德之人，其端兆不可睹，德趣不可见」。王弼着眼于不易从外表识定其意向。","【读法】冬涉川与畏四邻不必落实成恒常焦虑。譬喻取审慎而难测之状，不是在劝人把一切邻人都当作敌人。"]},{id:"five-images-of-bearing",label:"敦兮其若朴，旷兮其若谷",showLabel:!0,sentences:[[{text:"俨",glossary:"yan"},"兮其若客；"],[{text:"涣",glossary:"huan"},"兮若冰之将释；"],[{text:"敦",glossary:"dun"},"兮其若",{text:"朴",glossary:"pu"},"；"],[{text:"旷",glossary:"kuang"},"兮其若谷；"],[{text:"混",glossary:"hun"},"兮其若浊。"]],note:["【白话】恭敬庄重啊，像作客；舒散融解啊，像冰将要消融；敦厚质朴啊，像未经雕琢的木材；空阔能容啊，像山谷；浑融不自显啊，像浊水。","【王弼注择要】「凡此诸若，皆言其容象不可得而形名也。」王弼将这些不同形象合看，说明不能用固定外形与名目把这样的人框定。","【读法】七喻有紧有松、有恭敬也有空阔，不宜只抓谨慎或只抓洒脱。若浊也不是赞美污浊行为，而是从不自显清明的样态转到下文浊以静之徐清。"]},{id:"clearing-and-coming-to-life",label:"孰能浊以静之徐清",showLabel:!0,sentences:[["孰能浊以静之",{text:"徐",glossary:"xu"},"清？"],["孰能安以久动之徐生？"]],note:["【白话】谁能让浑浊的状态经由安静而慢慢澄清？谁能让安定的状态经由持续的发动而慢慢生发？前一句说静中澄清，后一句说动中生机。","【王弼注择要】「浊以静物则得清，安以动物则得生。」「孰能者，言其难也。徐者，详慎也。」注同时说静与动，且将徐解释为详审谨慎。","【读法】正文保留安以久动的次序，理解为安定中经较久的发动渐生。这里不强定唯一断句；两问的静、动互补，不能只抽出第一问推成永远不动。"]},{id:"not-seeking-fullness",label:"保此道者不欲盈",showLabel:!0,sentences:[["保此道者不欲",{text:"盈",glossary:"ying"},"。"],["夫唯不盈，故能",{text:"蔽",glossary:"bi"},"不新成。"]],note:["【白话】持守此道的人，不追求盈满。正因为不盈满，所以能够覆藏而不显为新成之状。末句语意难定，本页依王弼蔽作覆盖的训释暂这样理解。","【王弼注择要】「盈必溢也。」「蔽，覆盖也。」注提示盈满会溢出，末句则只给出蔽的字义，并未把整句的疑难完全消除。","【读法】不欲盈可读出不将自己填满、自足的方向；不新成不宜直接讲成反对创新。本页不静默改为其他通行整理中的敝而新成，保留本句及存疑。"]}],r=[{id:"shi",term:"士",sense:1},{id:"qiang",term:"强",sense:1,pinyin:"qiǎng"},{id:"rong",term:"容",sense:1},{id:"yu",term:"豫",sense:1},{id:"you",term:"犹",sense:1},{id:"yan",term:"俨",sense:1},{id:"huan",term:"涣",sense:1},{id:"dun",term:"敦",sense:1},{id:"pu",term:"朴",sense:1},{id:"kuang",term:"旷",sense:1},{id:"hun",term:"混",sense:1},{id:"xu",term:"徐",sense:1},{id:"ying",term:"盈",sense:1},{id:"bi",term:"蔽",sense:1}];return(x,e)=>{const i=t("DaoReadingPrelude"),l=t("DaoTextReading"),d=t("DaoLineGuide"),h=t("DaoKeywordCards");return c(),g("div",null,[e[0]||(e[0]=a("h1",{id:"道德经第十五章",tabindex:"-1"},[s("道德经第十五章 "),a("a",{class:"header-anchor",href:"#道德经第十五章","aria-label":'Permalink to "道德经第十五章"'},"​")],-1)),n(i,{title:"七个譬喻，为什么仍说不可识？",summary:"本章从善为士者难以识定说起，勉用涉川、畏邻、作客、冰释、朴、谷、浊七个譬喻描绘，继而转向静中澄清、动中生发。结尾以不欲盈收束，留下不把自己定满的方向。",points:[{label:"先读",text:"七个若各带出怎样的姿态？"},{label:"再辨",text:"谨慎与舒散、静与动为何并存？"},{label:"后想",text:"不欲盈怎样避免变成拒绝成长？"}],hint:"竹简模式先通读；经典阅读可展开段释义、点击标记字词查义。"}),e[1]||(e[1]=a("h2",{id:"【原典层】原文与段级释义",tabindex:"-1"},[s("【原典层】原文与段级释义 "),a("a",{class:"header-anchor",href:"#【原典层】原文与段级释义","aria-label":'Permalink to "【原典层】原文与段级释义"'},"​")],-1)),n(l,{sections:o,glossary:r,tone:"ink",density:"comfortable","aria-label":"《道德经》第十五章原文"}),e[2]||(e[2]=a("h2",{id:"【导读层】核心句引读",tabindex:"-1"},[s("【导读层】核心句引读 "),a("a",{class:"header-anchor",href:"#【导读层】核心句引读","aria-label":'Permalink to "【导读层】核心句引读"'},"​")],-1)),n(d,{lines:[{text:"夫唯不可识，故强为之容。",tone:"先知难描",guide:"七喻出现之前，作者先说明描摹的限度。读者可以借形象体会，不能反过来凭某种外貌认定谁已得道。"},{text:"混兮其若浊。",tone:"由貌转机",guide:"若浊承接前面的容貌描绘，又引出下文浊以静之徐清。清不必靠急于显清来取得，澄清也需要过程。"},{text:"孰能安以久动之徐生？",tone:"静动并读",guide:"第二问补出动与生。安静有其作用，发动也有其作用，关键是详慎地辨认何时该静、何时该动。"},{text:"保此道者不欲盈。",tone:"不自定满",guide:"持守并非把自己封成一个再无变化的成品。后一句有文字与解释难点，先抓住不求盈满的明确线索，再保留存疑。"}]}),e[3]||(e[3]=a("h2",{id:"【注释层】字词释义",tabindex:"-1"},[s("【注释层】字词释义 "),a("a",{class:"header-anchor",href:"#【注释层】字词释义","aria-label":'Permalink to "【注释层】字词释义"'},"​")],-1)),n(h,{items:r}),e[4]||(e[4]=m("",15))])}}});export{y as __pageData,_ as default};
